package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.monitoring.ObservationWindowAnalysis.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ObservationWindowDiagnosticControllerTest {
    static final String ACTOR="78000000-0000-4000-8000-000000000001",TENANT="78000000-0000-4000-8000-000000000002";
    PlatformRepository platform;ObservationWindowDiagnosticController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new ObservationWindowDiagnosticController(platform);member("padmin",true,7);}
    void member(String role,boolean active,long version){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,version,active)));}
    ObjectNode input(){var v=mapper.createObjectNode().put("hold_seconds","60").put("max_gap_seconds","60").put("observed_at","2026-10-21T00:01:00.000Z");v.set("condition",mapper.createObjectNode().put("comparison","LE").put("threshold","5.000").put("unit","%"));var rows=v.putArray("samples");for(String t:List.of("2026-10-21T00:00:00Z","2026-10-21T00:01:00Z"))rows.add(mapper.createObjectNode().put("recorded_at",t).put("state","KNOWN").put("value","1.00000000000000001").put("unit","%"));return v;}
    MockHttpServletRequest request(String body){var r=new MockHttpServletRequest("POST","/api/v1/monitoring/observation-window-diagnostics");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    Map<?,?> data(String body){return (Map<?,?>)((Map<?,?>)controller.analyze(request(body))).get("data");}
    @Test void authorizedCandidateReturnsExactInputsButNeverRecoveryAuthority(){var original=input();var out=data(original.toString());assertEquals(Status.MATCHING_SPAN_REACHED,out.get("status"));assertEquals(TENANT,out.get("tenant_id"));assertEquals(ACTOR,out.get("actor_id"));assertEquals(7L,out.get("permission_version"));assertEquals(original,mapper.valueToTree(out.get("inputs")));assertEquals("60.000",out.get("observed_span_seconds"));for(String k:List.of("publishable","units_converted","monitoring_applied","event_state_updated","recovery_confirmed","writes_performed"))assertEquals(false,out.get(k));assertNull(out.get("effective_rule"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void missingCandidateValuesReturnPendingWithoutDefaults(){var v=input().putNull("condition").putNull("hold_seconds").putNull("max_gap_seconds");var out=data(v.toString());assertEquals(Status.CONFIG_PENDING,out.get("status"));assertNull(out.get("candidate_span_reached"));assertNull(out.get("matching_sample_count"));}
    @Test void negativeDurationsConflictRatherThanRewrite(){assertEquals(Status.CONFLICT,data(input().put("hold_seconds","-1").toString()).get("status"));}
    @Test void latestUnknownMayRetainUnitMetadataButNotAValue(){var v=input();var last=(ObjectNode)v.withArray("samples").get(1);last.put("state","UNKNOWN").putNull("value");var out=data(v.toString());assertEquals(Status.UNKNOWN_LATEST,out.get("status"));assertNull(out.get("candidate_span_reached"));}
    @Test void emptySamplesAreNotHealthy(){var v=input();v.putArray("samples");var out=data(v.toString());assertEquals(Status.NO_SAMPLES,out.get("status"));assertNull(out.get("observed_span_seconds"));}
    @Test void unknownOverridesAndMissingFieldsAreRejected(){for(String key:List.of("tenant_id","rule_id","publishable","recovery_confirmed"))assertEquals(400,assertThrows(DomainException.class,()->data(input().put(key,"UNTRUSTED").toString())).status);var v=input();v.remove("samples");assertThrows(DomainException.class,()->data(v.toString()));}
    @Test void allQueryParametersAreRejected(){var r=request(input().toString());r.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.analyze(r)).status);}
    @Test void authorizationRunsBeforeParsingAndDoesNotReadOtherRepositories(){for(String role:List.of("viewer","tadmin","msp")){member(role,true,7);assertEquals(403,assertThrows(DomainException.class,()->data("not json")).status);}verify(platform,times(3)).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void inactiveMissingOrWrongMembershipNeverRunsDiagnostics(){member("padmin",false,7);assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);member("padmin",true,0);assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(TENANT,TENANT,"padmin",7,true)));assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);var r=request(input().toString());r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.analyze(r)).status);}
    @Test void duplicateKeysTrailingDocumentsAndDeepJsonAreRejected(){for(String raw:List.of(input()+" {}","{\"condition\":null,\"condition\":null}",input().toString().replace("\"state\":\"KNOWN\"","\"state\":\"KNOWN\",\"state\":\"UNKNOWN\""),"[[[[[[null]]]]]]"))assertEquals(400,assertThrows(DomainException.class,()->data(raw)).status);}
    @Test void bytesOverLimitAreRejectedWithoutTruncation(){assertEquals(413,assertThrows(DomainException.class,()->data(" ".repeat(ObservationWindowDiagnosticController.MAX_BODY_BYTES+1))).status);}
    @Test void numericValuesMustBeBoundedExactStrings(){for(var bad:List.of(mapper.getNodeFactory().numberNode(1),mapper.getNodeFactory().textNode("1e3"),mapper.getNodeFactory().textNode("-0"))){var v=input();((ObjectNode)v.withArray("samples").get(0)).set("value",bad);assertEquals(400,assertThrows(DomainException.class,()->data(v.toString())).status);}}
    @Test void malformedTimesDuplicatesAndFutureSamplesAreRejected(){for(String time:List.of("2026-02-30T00:00:00Z","2026-10-21T24:00:00Z","2026-10-21T23:59:60Z","2026-10-21T00:00:00+08:00","2026-10-21T00:00:00.0001Z"))assertEquals(400,assertThrows(DomainException.class,()->data(input().put("observed_at",time).toString())).status);var v=input();((ObjectNode)v.withArray("samples").get(1)).put("recorded_at","2026-10-21T00:00:00Z");assertThrows(DomainException.class,()->data(v.toString()));assertThrows(DomainException.class,()->data(input().put("observed_at","2026-10-21T00:00:00Z").toString()));}
    @Test void sampleLimitRejectsRatherThanComputingPrefix(){var v=input();var row=v.withArray("samples").get(0).deepCopy();for(int i=0;i<999;i++)v.withArray("samples").add(row);assertEquals(400,assertThrows(DomainException.class,()->data(v.toString())).status);}
    @Test void cacheAndReferrerHeadersArePrivate(){var r=new MockHttpServletResponse();controller.privateHeaders(r);assertEquals("no-store",r.getHeader("Cache-Control"));assertEquals("no-referrer",r.getHeader("Referrer-Policy"));}
}
